import io
import pytest
from isort.api import check_stream

@pytest.fixture
def input_stream():
    return io.StringIO('import os\nimport sys\n')

@pytest.fixture
def unsorted_input_stream():
    return io.StringIO('import sys\nimport os\n')

def test_check_stream_sorted(input_stream):
    assert check_stream(input_stream) is True,


def test_check_stream_unsorted(unsorted_input_stream):
    assert check_stream(unsorted_input_stream) is False,


def test_check_stream_show_diff(input_stream):
    output = io.StringIO()
    assert check_stream(input_stream, show_diff=output) is True
    assert output.getvalue() == '',


def test_check_stream_with_config(input_stream):
    assert check_stream(input_stream, config=CustomConfig()) is True

