import io
import pytest
from isort.api import check_stream

@pytest.fixture
def sorted_input_stream():
    return io.StringIO('import os\nimport sys\n')

@pytest.fixture
def unsorted_input_stream():
    return io.StringIO('import sys\nimport os\n')

@pytest.fixture
def unsorted_input_with_diff():
    return io.StringIO('import json\nimport os\nimport sys\n')

def test_check_stream_sorted(sorted_input_stream):
    assert check_stream(sorted_input_stream) is True

def test_check_stream_unsorted(unsorted_input_stream):
    assert check_stream(unsorted_input_stream) is False

def test_check_stream_show_diff(sorted_input_stream):
    output = io.StringIO()
    assert check_stream(sorted_input_stream, show_diff=output) is True
    assert output.getvalue() == ''

def test_check_stream_unsorted_show_diff(unsorted_input_stream):
    output = io.StringIO()
    assert check_stream(unsorted_input_stream, show_diff=output) is False
    assert 'Imports are incorrectly sorted' in output.getvalue()

def test_check_stream_with_diff(unsorted_input_with_diff):
    output = io.StringIO()
    assert check_stream(unsorted_input_with_diff, show_diff=output) is False
    assert 'Imports are incorrectly sorted and/or formatted.' in output.getvalue()

def test_check_stream_with_custom_config(unsorted_input_stream):
    class CustomConfig:
        color_output = False
        format_error = True
        format_success = True
        verbose = True
        only_modified = False

    assert check_stream(unsorted_input_stream, config=CustomConfig()) is False
